-- Migration 0011 (1.6.0): richer Intake forms (config column) and the two founder forms moved from artifacts.
ALTER TABLE intake_forms ADD COLUMN config TEXT;
INSERT OR IGNORE INTO intake_forms(id,title,about,audience,status,fields,config,created_by,created_at,updated_at) VALUES ('if_alignment','Founder Alignment','What should Unscrollable become? Twenty-two short questions. Answer alone, then compare.','founder','open','[{"id": "feel", "type": "multi", "section": "The feel", "label": "Unscrollable walks into a room. Which three words do people use about it afterwards?", "options": ["Calm", "Bold", "Playful", "Premium", "Direct", "Warm", "Sharp", "Quiet", "Unhinged", "Editorial", "Technical", "Human", "Minimal", "Loud"], "exact": 3}, {"id": "compare", "type": "long", "section": "The feel", "label": "If Unscrollable were someone people already know, who would it remind them of? And what is the one thing you would steal from them?", "ph": "A name, then the thing you would steal"}, {"id": "say", "type": "long", "section": "The feel", "label": "A founder hangs up after our first call and texts a friend about us. What does the text say?", "ph": "Write the actual message, in their voice"}, {"id": "place", "type": "pick", "section": "The feel", "label": "If Unscrollable were a place, which one would it be?", "options": ["A quiet library with great coffee", "A late-night workshop", "A members-only club", "A stage with the lights on", "A hotel lobby that runs perfectly"]}, {"id": "loud", "type": "slider", "section": "The feel", "label": "How loud should we be in public?", "min": 0, "max": 100, "def": 50, "unit": " / 100", "lo": "Whisper", "hi": "Shouting"}, {"id": "post", "type": "pick", "section": "The feel", "label": "You can only post one of these under our name this week. Which one makes you proudest?", "options": ["A brutally honest founder lesson", "A clean framework carousel", "A joke that gets 500 comments", "A quiet client win story", "A behind-the-scenes screenshot"]}, {"id": "never", "type": "long", "section": "The feel", "label": "What is the one thing that would make you cringe if we did it? A phrase, a post, a pitch.", "ph": "The thing you never want to see us do"}, {"id": "services", "type": "multi", "section": "Who we serve", "label": "A founder DMs us tonight and asks if we can help with something. Which of these would you happily say yes to?", "options": ["Profile rebuild", "Outbound DMs", "Ongoing management", "Ghostwriting", "Carousels and design", "One-off projects", "Audits", "Training"]}, {"id": "client", "type": "pick", "section": "Who we serve", "label": "Picture the client you would be excited to get on a call with Monday morning. Who are they?", "options": ["Founders on YC or Product Hunt", "Tech founders broadly", "Coaches and consultants", "Any founder whose personal brand is the offer", "Not decided yet"]}, {"id": "nogo", "type": "long", "section": "Who we serve", "label": "Name one kind of client we should say no to, even if they pay well.", "ph": "Who, and why"}, {"id": "scope", "type": "pick", "section": "Who we serve", "label": "A client asks for something outside our offer and will pay double. What do we do?", "options": ["Say no and protect the focus", "Say yes once, then decide", "Say yes and fold it into the offer", "Refer them to someone else"]}, {"id": "price", "type": "pick", "section": "Who we serve", "label": "How should our pricing feel to a client?", "options": ["Premium, few clients", "Fair and steady", "Cheap early to win trust", "Custom every time"]}, {"id": "own", "type": "multi", "section": "How we work", "label": "Which of these jobs would you gladly own and never want to hand off?", "options": ["Sales and calls", "Content and voice", "Delivery", "Systems and tools", "Finance and legal", "Brand and design", "Hiring contractors"]}, {"id": "avoid", "type": "multi", "section": "How we work", "label": "And which of these would you be glad to never touch again?", "options": ["Sales and calls", "Content and voice", "Delivery", "Systems and tools", "Finance and legal", "Brand and design", "Hiring contractors"]}, {"id": "hours", "type": "slider", "section": "How we work", "label": "In a normal week, how many hours would you really give us? Not the hopeful number, the real one.", "min": 0, "max": 60, "def": 10, "unit": " h", "lo": "Barely", "hi": "Full time"}, {"id": "conflict", "type": "pick", "section": "How we work", "label": "Two of us disagree on something big and neither backs down. What do we do?", "options": ["Vote, two against one", "Whoever owns that area decides", "Sleep on it and talk tomorrow", "Ask an outsider we trust", "Pause the work until we agree"]}, {"id": "feedback", "type": "pick", "section": "How we work", "label": "How do you want to hear hard feedback from a partner?", "options": ["Straight, right away", "Written, so I can think first", "On a call, with kindness", "In a weekly slot only"]}, {"id": "money", "type": "pick", "section": "Money and future", "label": "It is the end of year one and you are quietly happy. What happened?", "options": ["Cover costs only", "1 paid client", "3 paid clients", "5 paid clients", "10 or more"]}, {"id": "money_n", "type": "slider", "section": "Money and future", "label": "The first money comes in. How much of every 100 should go straight back into Unscrollable?", "min": 0, "max": 100, "def": 50, "unit": "%", "lo": "", "hi": ""}, {"id": "future", "type": "pick", "section": "Money and future", "label": "Three years from now a friend asks what you are building. What do you tell them?", "options": ["A small studio we love", "An offer that scales without us", "We sold it", "We built software instead", "No idea yet"]}, {"id": "future_text", "type": "long", "section": "Money and future", "label": "And the quiet question: what would make you walk away?", "ph": "Be honest. Nobody grades this."}, {"id": "unsaid", "type": "long", "section": "Money and future", "label": "Last one. What have you been thinking about Unscrollable that you have not said out loud yet?", "ph": "Say it here first"}]','{"view": "compare", "reveal": "all", "time": "About ten minutes", "intro": "There are no right answers. Go with your first instinct and answer alone. When all three of you are done, the answers appear side by side. The gaps are the interesting part, so do not guess what the others will say."}','Tabish','2026-11-04T00:00:00.000Z','2026-11-04T00:00:00.000Z');
INSERT OR IGNORE INTO intake_forms(id,title,about,audience,status,fields,config,created_by,created_at,updated_at) VALUES ('if_traits','Founder Traits','How do you work, really? Twenty questions that turn into a profile for each of you and a team view.','founder','open','[{"id": "q1", "type": "pick", "section": "Under pressure", "label": "A client deliverable is due Friday. It is Wednesday night and you are 60% done. What do you do?", "options": ["Work late and finish it tonight", "Cut the scope and ship a smaller version", "Tell the client early and move the date", "Hand a piece to a partner"], "weights": [{"C": 2}, {"S": 1, "O": 1}, {"A": 1, "C": -1, "S": 1}, {"E": 1, "A": 1, "C": -1}]}, {"id": "q2", "type": "slider", "section": "Under pressure", "label": "How planned is your normal week?", "min": 0, "max": 100, "def": 50, "unit": "", "lo": "I wing it", "hi": "Every hour planned", "w": {"C": 2}}, {"id": "q3", "type": "pick", "section": "Under pressure", "label": "Monday morning. Forty things need you. What is your first move?", "options": ["Sort by deadline and attack", "Knock out the easy ones for momentum", "Ignore what is not mine", "Ask the team what matters most"], "weights": [{"C": 2}, {"E": 1}, {"C": 1, "A": -1}, {"A": 1, "E": 1, "C": -1}]}, {"id": "q4", "type": "slider", "section": "Under pressure", "label": "A plan changes at the last minute. How do you feel?", "min": 0, "max": 100, "def": 50, "unit": "", "lo": "Annoyed", "hi": "Excited", "w": {"O": 2}}, {"id": "q5", "type": "pick", "section": "New ideas", "label": "A partner pitches a wild idea that breaks our current offer. What is your reaction?", "options": ["Test it this week", "Ask for numbers first", "Park it until the current thing works", "Curious, but nervous"], "weights": [{"O": 2}, {"C": 1, "O": -1}, {"C": 2, "O": -1}, {"O": 1, "S": -1, "A": 1}]}, {"id": "q6", "type": "pick", "section": "New ideas", "label": "You get a free Saturday. Which one pulls you most?", "options": ["Learning a skill with no use yet", "Fixing and tidying our systems", "Meeting new people in our space", "Offline, nobody around"], "weights": [{"O": 2}, {"C": 2, "O": -1}, {"E": 2}, {"E": -2, "S": 1}]}, {"id": "q7", "type": "slider", "section": "People", "label": "After a full day of calls, how do you feel?", "min": 0, "max": 100, "def": 50, "unit": "", "lo": "Drained", "hi": "Fired up", "w": {"E": 2}}, {"id": "q8", "type": "pick", "section": "People", "label": "A post of yours goes live. What do you do?", "options": ["Reply to every comment", "Check once, then move on", "Wait and watch the numbers", "Share it in three groups"], "weights": [{"E": 2, "A": 1}, {"S": 1}, {"C": 1, "E": -1}, {"E": 2, "C": 1}]}, {"id": "q9", "type": "pick", "section": "People", "label": "A partner shares work you think is weak. What do you do?", "options": ["Say it straight, right now", "Name what works first, then the gap", "Fix it quietly myself", "Ask questions until they see it"], "weights": [{"A": -2, "E": 1}, {"A": 1}, {"C": 1, "E": -1}, {"A": 1, "O": 1}]}, {"id": "q10", "type": "pick", "section": "People", "label": "Two partners argue and you are in the middle. What do you do?", "options": ["Step in and decide", "Listen to both and find the middle", "Stay out of it", "Call a break and let it cool"], "weights": [{"E": 2, "A": -1}, {"A": 2}, {"E": -1, "A": -1}, {"S": 2}]}, {"id": "q11", "type": "slider", "section": "People", "label": "How much does it matter to you that people like you?", "min": 0, "max": 100, "def": 50, "unit": "", "lo": "Barely", "hi": "A lot", "w": {"A": 2}}, {"id": "q12", "type": "pick", "section": "Steadiness", "label": "A big prospect goes silent after a great call. What happens in your head?", "options": ["I follow up twice, calmly", "I replay the call for hours", "I move to the next lead", "I ask a partner what I did wrong"], "weights": [{"S": 2}, {"S": -2}, {"S": 1}, {"S": -1, "A": 1}]}, {"id": "q13", "type": "slider", "section": "Steadiness", "label": "How fast do you bounce back after a bad day?", "min": 0, "max": 100, "def": 50, "unit": "", "lo": "Slowly", "hi": "By morning", "w": {"S": 2}}, {"id": "q14", "type": "pick", "section": "Steadiness", "label": "Money is tight in month three. What is your honest reaction?", "options": ["I get quieter and work harder", "I get blunt with the team", "I stay calm and cut costs", "I look for a bigger bet"], "weights": [{"S": -1, "C": 1}, {"S": -1, "A": -1}, {"S": 2, "C": 1}, {"O": 2}]}, {"id": "best", "type": "multi", "section": "Strengths and gaps", "label": "Which of these do you do well without trying?", "options": ["Sales and calls", "Content and voice", "Delivery", "Systems and tools", "Finance and legal", "Brand and design", "Hiring and managing"]}, {"id": "drain", "type": "multi", "section": "Strengths and gaps", "label": "Which of these drains you fastest?", "options": ["Sales and calls", "Content and voice", "Delivery", "Systems and tools", "Finance and legal", "Brand and design", "Hiring and managing"]}, {"id": "decide", "type": "pick", "section": "How you work", "label": "How do you make a big decision?", "options": ["Gut first, then check", "Data first, then gut", "Talk it out with someone", "Sleep on it"], "weights": [{}, {"C": 1}, {"E": 1}, {"S": 1}], "style": "How I decide"}, {"id": "rhythm", "type": "pick", "section": "How you work", "label": "What rhythm works best with partners?", "options": ["Short check ins every day", "One deep sync a week", "Written updates, no calls", "Only when something needs deciding"], "weights": [{"E": 1}, {"C": 1}, {"E": -1}, {}], "style": "How I work with partners"}, {"id": "upset", "type": "pick", "section": "How you work", "label": "When you are upset with a partner, what do you do?", "options": ["Say it the same day", "Write it down first, then share", "Wait until it passes", "Hint and hope they notice"], "weights": [{"A": -1, "S": 1}, {"C": 1}, {"S": -1}, {"A": 1, "S": -1}], "style": "When I am upset"}, {"id": "text_a", "type": "long", "section": "The honest bit", "label": "Partners tend to underestimate my...", "ph": "Nobody grades this.", "own": "Partners underestimate my"}, {"id": "text_b", "type": "long", "section": "The honest bit", "label": "Partners should watch out for my...", "ph": "Nobody grades this.", "own": "Partners should watch out for my"}]','{"view": "traits", "reveal": "all", "time": "About eight minutes", "intro": "Go with your first instinct. When you finish you see your own profile straight away. The team view opens when all three of you are done. This is a conversation starter, not a clinical test. It shows how you described yourself today.", "best": "best", "drain": "drain", "traits": {"O": {"n": "Curiosity", "lo": "Prefers proven ground", "hi": "Chases new ideas", "L": "You like what is tested and you trust it.", "M": "You test new things when there is a reason.", "H": "You get pulled toward new ideas and want to try them."}, "C": {"n": "Follow-through", "lo": "Loose and flexible", "hi": "Planned and finishes", "L": "You work in bursts and adapt on the fly.", "M": "You plan the big things and wing the rest.", "H": "You plan, you track, and you finish what you start."}, "E": {"n": "Social energy", "lo": "Recharges alone", "hi": "Recharges with people", "L": "You do your best thinking alone and need quiet after calls.", "M": "You enjoy people in doses.", "H": "People give you energy. Calls and rooms are fuel."}, "A": {"n": "Harmony", "lo": "Direct, will challenge", "hi": "Smooths, will support", "L": "You say the hard thing and expect others to do the same.", "M": "You balance honesty and kindness depending on the day.", "H": "You protect the relationship first and the point second."}, "S": {"n": "Steadiness", "lo": "Feels pressure fast", "hi": "Stays level", "L": "Pressure hits you early, so tell partners when it does.", "M": "You hold up well, with a few things that rattle you.", "H": "You stay level when things go wrong, and partners lean on that."}}}','Tabish','2026-11-04T00:00:00.000Z','2026-11-04T00:00:00.000Z');
INSERT OR IGNORE INTO intake_responses(id,form_id,who,answers,source,created_by,created_at,updated_at) VALUES ('ir_seed_align_tabish','if_alignment','Tabish','{"avoid": ["Content and voice", "Sales and calls"], "client": "Any founder whose personal brand is the offer", "compare": "Don''t have answer yet", "conflict": "Sleep on it and talk tomorrow", "feedback": "Written, so I can think first", "feel": ["Editorial", "Playful", "Bold"], "future_text": "If we don''t align anymore", "hours": 40, "loud": 74, "money": "3 paid clients", "money_n": 20, "never": "Unthoughtfull", "nogo": "The one who doesn''t value our time", "own": ["Brand and design", "Finance and legal", "Hiring contractors", "Delivery", "Systems and tools"], "place": "A stage with the lights on", "post": "A behind-the-scenes screenshot", "price": "Fair and steady", "say": "These guys know their fucking stuff", "scope": "Say yes and fold it into the offer", "services": ["Profile rebuild", "Outbound DMs", "Ongoing management", "Ghostwriting", "Carousels and design"], "unsaid": "I want it to go viral asap"}','founder','Tabish','2026-10-31T21:47:05.532Z','2026-10-31T21:47:05.532Z');
INSERT OR IGNORE INTO intake_responses(id,form_id,who,answers,source,created_by,created_at,updated_at) VALUES ('ir_seed_traits_tabish','if_traits','Tabish','{"best": ["Systems and tools", "Hiring and managing", "Brand and design", "Finance and legal"], "decide": "Gut first, then check", "drain": ["Sales and calls", "Content and voice", "Delivery"], "q1": "Work late and finish it tonight", "q10": "Listen to both and find the middle", "q11": 24, "q12": "I ask a partner what I did wrong", "q13": 80, "q14": "I look for a bigger bet", "q2": 82, "q3": "Ask the team what matters most", "q4": 43, "q5": "Park it until the current thing works", "q6": "Meeting new people in our space", "q7": 26, "q8": "Reply to every comment", "q9": "Ask questions until they see it", "rhythm": "One deep sync a week", "text_a": "Skill quotient", "text_b": "Back", "upset": "Wait until it passes"}','founder','Tabish','2026-11-02T07:28:51.216Z','2026-11-02T07:28:51.216Z');
